'use strict';
const fs = require('fs');
const path = require('path');

const DIR = '/tmp/neutrino-fast-live-PgKqxR/parallel_analysis/standard/0';
const REGIONS = ['north', 'south', 'east', 'west'];
const failures = [];
const checks = [];
function check(name, ok, detail) {
  checks.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ' :: ' + detail : ''}`);
  if (!ok) failures.push(name);
}
function isInt(v) { return Number.isInteger(v) && v >= 0; }

// ---- 1. no unrelated inputs in the fixture ----
const entries = fs.readdirSync(DIR, { withFileTypes: true }).map(d => d.name).sort();
const expected = ['answer.json', ...REGIONS.map(r => r + '.json')].sort();
check('fixture contains only answer.json + 4 sources',
  JSON.stringify(entries) === JSON.stringify(expected),
  entries.join(', '));

// ---- 2. answer.json parses and matches required schema ----
const answerPath = path.join(DIR, 'answer.json');
let answer;
try { answer = JSON.parse(fs.readFileSync(answerPath, 'utf8')); }
catch (e) { check('answer.json parses as JSON', false, e.message); report(); }
check('answer.json parses as JSON', true);
check('answer.json is a plain object', answer !== null && typeof answer === 'object' && !Array.isArray(answer));
check('top-level keys are exactly regions, grand_units, grand_weighted',
  JSON.stringify(Object.keys(answer).sort()) === JSON.stringify(['grand_units', 'grand_weighted', 'regions']),
  Object.keys(answer).join(', '));
check('regions is a plain object', answer.regions !== null && typeof answer.regions === 'object' && !Array.isArray(answer.regions));
check('regions keyed exactly north/south/east/west',
  answer.regions && JSON.stringify(Object.keys(answer.regions).sort()) === JSON.stringify(REGIONS.slice().sort()),
  answer.regions ? Object.keys(answer.regions).join(', ') : 'missing');
check('grand_units is a non-negative integer', isInt(answer.grand_units), String(answer.grand_units));
check('grand_weighted is a non-negative integer', isInt(answer.grand_weighted), String(answer.grand_weighted));

// ---- 3. recompute every source independently, verify per-region values ----
const recomputed = {};
let totalRecords = 0, allUnits = 0, allWeighted = 0, idsSeen = 0;
for (const region of REGIONS) {
  const file = path.join(DIR, region + '.json');
  if (!fs.existsSync(file)) { check(`${region}.json exists`, false); continue; }
  check(`${region}.json exists`, true);
  let data;
  try { data = JSON.parse(fs.readFileSync(file, 'utf8')); }
  catch (e) { check(`${region}.json parses`, false, e.message); continue; }
  check(`${region}.json parses`, true);
  check(`${region}.json is an array`, Array.isArray(data), Array.isArray(data) ? `${data.length} records` : typeof data);
  if (!Array.isArray(data)) continue;

  let malformed = 0, units = 0, weighted = 0, localIds = new Set();
  for (const rec of data) {
    const keys = rec && typeof rec === 'object' && !Array.isArray(rec) ? Object.keys(rec).sort() : [];
    const okShape = JSON.stringify(keys) === JSON.stringify(['id', 'units', 'weight']);
    const okVals = okShape && isInt(rec.id) && isInt(rec.units) && isInt(rec.weight);
    if (!okVals) { malformed++; continue; }
    if (localIds.has(rec.id)) malformed++;
    localIds.add(rec.id);
    units += rec.units;
    weighted += rec.units * rec.weight;
  }
  check(`${region}.json every record well-formed (id/units/weight ints, unique)`, malformed === 0, `${malformed} bad of ${data.length}`);

  const count = data.length;
  recomputed[region] = { count, units, weighted };
  totalRecords += count; allUnits += units; allWeighted += weighted; idsSeen += localIds.size;

  const got = answer.regions && answer.regions[region];
  check(`regions.${region} exists`, !!got);
  if (!got) continue;
  check(`regions.${region} keys are exactly count, units, weighted`,
    JSON.stringify(Object.keys(got).sort()) === JSON.stringify(['count', 'units', 'weighted']),
    Object.keys(got).join(', '));
  check(`regions.${region} all fields non-negative integers`,
    isInt(got.count) && isInt(got.units) && isInt(got.weighted), JSON.stringify(got));
  check(`regions.${region}.count === records in ${region}.json`, got.count === count, `${got.count} vs ${count}`);
  check(`regions.${region}.units === sum(units) of ${region}.json`, got.units === units, `${got.units} vs ${units}`);
  check(`regions.${region}.weighted === sum(units*weight) of ${region}.json`, got.weighted === weighted, `${got.weighted} vs ${weighted}`);
}

// ---- 4. grand totals ----
const regionSumUnits = REGIONS.reduce((s, r) => s + (recomputed[r] ? recomputed[r].units : 0), 0);
const regionSumWeighted = REGIONS.reduce((s, r) => s + (recomputed[r] ? recomputed[r].weighted : 0), 0);
check('every record in every source counted (region counts sum to records read)',
  REGIONS.every(r => recomputed[r]) && totalRecords === REGIONS.reduce((s, r) => s + recomputed[r].count, 0) && idsSeen === totalRecords,
  `records=${totalRecords}, ids=${idsSeen}`);
check('grand_units === sum of all four sources\' units', answer.grand_units === allUnits, `${answer.grand_units} vs ${allUnits}`);
check('grand_weighted === sum of all four sources\' units*weight', answer.grand_weighted === allWeighted, `${answer.grand_weighted} vs ${allWeighted}`);
check('grand_units === sum of regions.units', answer.grand_units === regionSumUnits, `${answer.grand_units} vs ${regionSumUnits}`);
check('grand_weighted === sum of regions.weighted', answer.grand_weighted === regionSumWeighted, `${answer.grand_weighted} vs ${regionSumWeighted}`);

report();

function report() {
  console.log(checks.join('\n'));
  console.log('---');
  console.log('recomputed from sources:', JSON.stringify(recomputed));
  console.log(`sources read: ${REGIONS.length}, records counted: ${totalRecords}, sum(units)=${allUnits}, sum(units*weight)=${allWeighted}`);
  console.log(failures.length === 0
    ? `VALIDATION PASSED (${checks.length} checks, 0 failures)`
    : `VALIDATION FAILED (${failures.length} of ${checks.length} checks): ${failures.join('; ')}`);
  process.exit(failures.length === 0 ? 0 : 1);
}

